import {
  IObstacleCreateDTO,
  IObstacleUpdateDTO,
  ObstacleCategoryDTO,
  ObstacleTypeDTO,
} from '../@types/obstacles.dto.types';
import { IObstacle, ObstacleCategory, ObstacleType } from '../@types/obstacles.types';

const mapObstacleTypeToBackDTO = (data: ObstacleType): ObstacleTypeDTO => {
  const map: Record<ObstacleType, ObstacleTypeDTO> = {
    [ObstacleType.Pass]: 'pass',
    [ObstacleType.Peak]: 'peak',
    [ObstacleType.Poi]: 'poi',
  };

  return map[data];
};

const mapObstacleCategoryToBackDTO = (data: ObstacleCategory): ObstacleCategoryDTO => {
  const map: Record<ObstacleCategory, ObstacleCategoryDTO> = {
    [ObstacleCategory.CategoryNo]: 'no',
    [ObstacleCategory.Category1a]: '1a',
    [ObstacleCategory.Category1b]: '1b',
    [ObstacleCategory.Category2a]: '2a',
    [ObstacleCategory.Category2b]: '2b',
    [ObstacleCategory.Category3a]: '3a',
    [ObstacleCategory.Category3b]: '3b',
    [ObstacleCategory.Category4a]: '4a',
    [ObstacleCategory.Category4b]: '4b',
    [ObstacleCategory.Category5a]: '5a',
    [ObstacleCategory.Category5b]: '5b',
    [ObstacleCategory.Category6a]: '6a',
    [ObstacleCategory.Category6b]: '6b',
  };

  return map[data];
};

export const mapFrontObstacleToCreateDto = (data: IObstacle): IObstacleCreateDTO => {
  return {
    name: data.name,
    description: data.description,
    lat: data.coordinates[0],
    lon: data.coordinates[1],
    alt: data.altitude,
    link: data.link,
    comment: data.comment,
    type: mapObstacleTypeToBackDTO(data.type),
    category: mapObstacleCategoryToBackDTO(data.category),
    id_geo_region: data.region ? data.region.id : null,
  };
};

export const mapFrontObstacleToUpdateDto = (data: IObstacle): IObstacleUpdateDTO => {
  return {
    id: data.id,
    ...mapFrontObstacleToCreateDto(data),
  };
};
