import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapFrontObstacleToCreateDto,
  mapFrontObstacleToUpdateDto,
} from '../@mappers/obstacles.toBack.mapper';
import {
  mapObstacleDTOToFront,
  mapObstacleForUserDTOToFront,
} from '../@mappers/obstacles.toFront.mapper';
import {
  IObstacleCreateDTO,
  IObstacleDTO,
  IObstaclesForUserDTO,
  IObstacleUpdateDTO,
} from '../@types/obstacles.dto.types';
import { IObstacle, IObstacleForUser, ObstacleType } from '../@types/obstacles.types';

export const getObstaclesAsync = async (options?: {
  type?: ObstacleType;
}): Promise<IObstacle[]> => {
  const res = await get<IObstacleDTO[]>('/ajax/obstacles/list.php', options).then(handleApiError);
  return res.map(mapObstacleDTOToFront);
};

export const getOneObstacleAsync = async (id: number): Promise<IObstacle> => {
  const res = await get<IObstacleDTO>('/ajax/obstacles/one.php', { id }).then(handleApiError);
  return mapObstacleDTOToFront(res);
};

export const addObstacleAsync = async (obstacle: IObstacle): Promise<IObstacle> => {
  const data = mapFrontObstacleToCreateDto(obstacle);
  const res = await post<{ id: number }, IObstacleCreateDTO>('/ajax/obstacles/add.php', data).then(
    handleApiError,
  );
  return {
    ...obstacle,
    ...res,
  };
};

export const updateObstacleAsync = async (obstacle: IObstacle): Promise<IObstacle> => {
  const data = mapFrontObstacleToUpdateDto(obstacle);
  await post<{ success: boolean }, IObstacleUpdateDTO>('/ajax/obstacles/edit.php', data).then(
    handleApiError,
  );
  return obstacle;
};

export interface ISearchObstacleCriteria {
  query?: string;
  lat?: number;
  lon?: number;
  radius?: number;
  bounds?: [number, number, number, number];
}

export const searchObstacleAsync = async (data: ISearchObstacleCriteria): Promise<IObstacle[]> => {
  const res = await get<IObstacleDTO[]>('/ajax/obstacles/list.php', {
    ...data,
    ...(data.bounds ? { bounds: data.bounds.join(',') } : {}),
  }).then(handleApiError);
  return res.map(mapObstacleDTOToFront);
};

export const getObstaclesForUserAsync = async (criteria?: {
  type?: ObstacleType;
  id_user?: number;
}): Promise<IObstacleForUser[]> => {
  const res = await get<IObstaclesForUserDTO[]>('/ajax/obstacles/for_user.php', criteria).then<
    IObstaclesForUserDTO[]
  >(handleApiError);
  return res.map(mapObstacleForUserDTOToFront);
};
